  const [showMappingResultsModal, setShowMappingResultsModal] = useState(false);
  const [newBannerGroups, setNewBannerGroups] = useState<BannerGroup[]>([]);
  const [showBannerBuilder, setShowBannerBuilder] = useState(false);
  const [editingBannerGroup, setEditingBannerGroup] = useState<BannerGroup | null>(null);
  const [selectedNewBannerGroupId, setSelectedNewBannerGroupId] = useState<string | null>(null);
  const [selectedNewBannerVariable, setSelectedNewBannerVariable] = useState<string | null>(null);
  const [bannerFilterConditions, setBannerFilterConditions] = useState<BannerConditionGroup[] | null>(null);
  const [parsedFile, setParsedFile] = useState<ParsedDataFile | null>(null);
  const [mappingFilter, setMappingFilter] = useState<'all' | 'mapped' | 'unmapped'>('all');
  const [singleSelectSort, setSingleSelectSort] = useState<Record<string, { column: 'code' | 'count' | 'percentage', direction: 'asc' | 'desc' }>>({});
  const [hiddenFromBanners, setHiddenFromBanners] = useState<Set<string>>(new Set());
  const [showDataCutsView, setShowDataCutsView] = useState(false);
  const [dataCutsLoading, setDataCutsLoading] = useState(false);
  const [dataCutsReady, setDataCutsReady] = useState(false);
  // Ref to open banner settings from the top-level toolbar while editing
  const bannerSettingsOpenRef = React.useRef<(() => void) | null>(null);
  // Banner Specs import (Excel) - for creating banner groups from file
  const bannerSpecsFileInputRef = React.useRef<HTMLInputElement | null>(null);
  const handleClickImportBannerSpecs = () => {
    bannerSpecsFileInputRef.current?.click();
  };
  const handleBannerSpecsFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      const file = e.target.files?.[0];
      if (!file) return;
      const arrayBuffer = await file.arrayBuffer();
      const wb = XLSX.read(arrayBuffer, { type: 'array' });
      if (!wb.SheetNames || wb.SheetNames.length === 0) {
        alert('No sheets found in the uploaded file.');
        return;
      }
      const sheet = wb.Sheets[wb.SheetNames[0]];
      const rows: any[][] = XLSX.utils.sheet_to_json(sheet, { header: 1 }) as any[][];
      if (!rows || rows.length === 0) {
        alert('The uploaded sheet is empty.');
        return;
      }
      // Find header row and column indices for the three columns
      let headerRowIndex = -1;
      let headingCol = -1;
      let pointCol = -1;
      let defCol = -1;
      // Try to detect by exact header match first, then by startsWith
      for (let i = 0; i < Math.min(rows.length, 10); i++) {
        const row = rows[i] || [];
        const lowered = row.map((c: any) => String(c || '').trim().toLowerCase());
        const idxHeading = lowered.findIndex((c: string) => c === 'banner heading (e.g. gender)' || c.startsWith('banner heading'));
        const idxPoint = lowered.findIndex((c: string) => c === 'banner point (e.g. male)' || c.startsWith('banner point'));
        const idxDef = lowered.findIndex((c: string) => c === 'banner definition' || c.startsWith('banner definition'));
        if (idxHeading !== -1 && idxPoint !== -1 && idxDef !== -1) {
          headerRowIndex = i;
          headingCol = idxHeading;
          pointCol = idxPoint;
          defCol = idxDef;
          break;
        }
      }
      if (headerRowIndex === -1) {
        alert('Could not find required headers: "Banner Heading", "Banner Point", "Banner Definition".');
        return;
      }
      // Build subgroups grouped by heading (preserve order), carry forward blank headings
      const subGroupMap = new Map<string, { id: string; title: string; cuts: any[] }>();
      let includeTotal = false;
      let currentHeading: string | null = null;
      for (let r = headerRowIndex + 1; r < rows.length; r++) {
        const row = rows[r] || [];
        const headingRaw = row[headingCol];
        const pointRaw = row[pointCol];
        const defRaw = defCol !== -1 ? row[defCol] : '';

        const headingCell = headingRaw !== undefined && headingRaw !== null ? String(headingRaw).trim() : '';
        const point = pointRaw !== undefined && pointRaw !== null ? String(pointRaw).trim() : '';
        const definitionText = defRaw !== undefined && defRaw !== null ? String(defRaw).trim() : '';

        // Skip completely blank rows
        if (!headingCell && !point) continue;

        // If a heading cell is present and equals "Total", mark and skip; don't set currentHeading
        if (headingCell && headingCell.toLowerCase() === 'total') {
          includeTotal = true;
          continue;
        }

        // Update current heading when a non-empty, non-total heading is present
        if (headingCell) {
          currentHeading = headingCell;
        }

        // We need a valid heading context and a point to create a cut
        if (!currentHeading || !point) continue;

        // Ensure subgroup for current heading exists
        if (!subGroupMap.has(currentHeading)) {
          subGroupMap.set(currentHeading, { id: `${Date.now()}-${subGroupMap.size + 1}`, title: currentHeading, cuts: [] });
        }
        const sub = subGroupMap.get(currentHeading)!;
        sub.cuts.push({
          id: `${sub.id}-c${sub.cuts.length + 1}`,
          title: point,
          variableName: '',
          codes: [],
          definitionText
        });
      }
      if (subGroupMap.size === 0) {
        alert('No banner headings/points found to import.');
        return;
      }
      const importedGroup: BannerGroup = {
        id: `import_${Date.now()}`,
        title: file.name.replace(/\.(xlsx|xls)$/i, '') || 'Imported Banner Specs',
        groups: Array.from(subGroupMap.values()).map(sg => ({ id: sg.id, title: sg.title, cuts: sg.cuts })),
        includeTotal
      };
      // Add to list and open in editor for review
      setNewBannerGroups(prev => [...prev, importedGroup]);
      setEditingBannerGroup(importedGroup);
      setShowBannerBuilder(true);
    } catch (err: any) {
      alert(`Failed to import banner specs: ${err?.message || String(err)}`);
    } finally {
      // reset input
      if (e.target) e.target.value = '';
    }
  };
  const [showSingleSelectGridSummary, setShowSingleSelectGridSummary] = useState<Record<string, boolean>>({});
  const [selectedSummaryNets, setSelectedSummaryNets] = useState<Record<string, Set<string>>>({});
  const [savedSummaryTables, setSavedSummaryTables] = useState<Record<string, Array<{ id: string, selectedNets: string[], baseQuestionNumber: string, customName?: string }>>>({});
  const [previewVariable, setPreviewVariable] = useState<Variable | null>(null);
  const [previewSectionsHtml, setPreviewSectionsHtml] = useState<PreviewTableSection[]>([]);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [previewError, setPreviewError] = useState<string | null>(null);
  const [previewDebugInfo, setPreviewDebugInfo] = useState<Record<string, TableDebugEntry>>({});
  // Track rendered table counts for each variable (for comparison with included counts)
  const [variableRenderedTableCounts, setVariableRenderedTableCounts] = useState<Record<string, number>>({});
  const getTabSpecsStorageKey = useCallback((suffix: string) => {
    return selectedQuestionnaire?.id ? `tabSpecs_${suffix}_${selectedQuestionnaire.id}` : null;
  }, [selectedQuestionnaire?.id]);

  // Helper function to format percentages based on decimal setting
  const formatPercentage = useCallback((value: number): string => {
    return `${value.toFixed(percentageDecimals)}%`;
  }, [percentageDecimals]);

  const getCodeValueForMean = useCallback((variableRef: Variable | { name?: string } | string | null, code: string, fallback?: string): number | null => {
    const directValue = getNumericCodeValueForMean(code, fallback);
    if (directValue !== null) return directValue;
    if (!variableRef) return null;

    const variableName = typeof variableRef === 'string' ? variableRef : variableRef?.name;
    if (!variableName) return null;

    const baseQuestionNumber = getBaseQuestionNumber(variableName);
    const normalizedBase = baseQuestionNumber.replace(/^Q/i, '');
    const question = questionnaireQuestions.find((q: any) => {
      const qNum = q.number || q.id;
      if (!qNum) return false;
      const qStr = String(qNum);
      const normalizedQ = qStr.replace(/^Q/i, '');
      return qStr === baseQuestionNumber ||
             normalizedQ === normalizedBase ||
             qStr === normalizedBase ||
             `Q${normalizedQ}` === baseQuestionNumber;
    });

    const tryParseCandidate = (candidate?: string | number): number | null => {
      if (candidate === null || candidate === undefined || candidate === '') return null;
      if (typeof candidate === 'number' && Number.isFinite(candidate)) {
        if (candidate >= 90 && candidate <= 99) return null;
        return candidate;
      }
      return getNumericCodeValueForMean(String(candidate));
    };

    const deriveValueFromOption = (option: any): number | null => {
      if (!option) return null;
      const fromCode = tryParseCandidate(option.code);
      if (fromCode !== null) return fromCode;
      const fromDisplay = tryParseCandidate(option.displayCode);
      if (fromDisplay !== null) return fromDisplay;
      const fromValue = tryParseCandidate(option.value);
      if (fromValue !== null) return fromValue;
      const fromOrder = tryParseCandidate(option.order);
      if (fromOrder !== null) return fromOrder;
      return null;
    };

    const normalizedTarget = normalizeCodeForComparison(code) || normalizeCodeForComparison(fallback);
    const labelValue = typeof variableRef === 'object' ? (variableRef as Variable)?.codes?.[code] : undefined;
    const normalizedLabel = typeof labelValue === 'string' ? labelValue.trim().toLowerCase() : '';

    const findMatchingOption = (options?: any[]) => {
      if (!options || options.length === 0) return null;
      return options.find((opt: any) => {
        if (normalizedTarget) {
          const optionCandidates = [
            opt?.code,
            opt?.value,
            opt?.displayCode,
            typeof opt?.order === 'number' ? opt.order : undefined
          ];
          if (optionCandidates.some((candidate) => candidate !== undefined && normalizeCodeForComparison(candidate) === normalizedTarget)) {
            return true;
          }
        }
        if (normalizedLabel) {
          const potentialLabels = [opt?.text, opt?.label, opt?.description]
            .filter(Boolean)
            .map((val: any) => String(val).trim().toLowerCase());
          if (potentialLabels.some(label => label === normalizedLabel)) {
            return true;
          }
        }
        return false;
      }) || null;
    };

    const variableCodesOrder = typeof variableRef === 'object' ? Object.keys((variableRef as Variable)?.codes || {}) : [];

    if (question && Array.isArray(question.responseOptions) && question.responseOptions.length > 0) {
      const optionMatch = findMatchingOption(question.responseOptions);
      if (optionMatch) {
        const derived = deriveValueFromOption(optionMatch);
        if (derived !== null) return derived;
        const optionIndex = question.responseOptions.indexOf(optionMatch);
        if (optionIndex >= 0) {
          const positionValue = getNumericCodeValueForMean(String(optionIndex + 1));
          if (positionValue !== null) return positionValue;
        }
      }

      if (variableCodesOrder.length > 0 && variableCodesOrder.length === question.responseOptions.length) {
        const idx = variableCodesOrder.indexOf(code);
        if (idx >= 0) {
          const option = question.responseOptions[idx];
          const derived = deriveValueFromOption(option);
          if (derived !== null) return derived;
        }
      }
    }

    if (variableCodesOrder.length > 0) {
      const idx = variableCodesOrder.indexOf(code);
      if (idx >= 0) {
        const fallbackFromOrder = getNumericCodeValueForMean(String(idx + 1));
        if (fallbackFromOrder !== null) return fallbackFromOrder;
      }
    }

    return null;
  }, [questionnaireQuestions, getBaseQuestionNumber]);

  const tabSpecsTypeOptions = useMemo(() => {
    const typeSet = new Set<string>();
    variables.forEach(variable => {
      if ((variable as any).isScaleSummary) return;
      if (!variable.type) {
        typeSet.add('Unknown');
      } else {
        typeSet.add(variable.type);
      }
    });
    return Array.from(typeSet).sort((a, b) => a.localeCompare(b));
  }, [variables]);

  const getStatsSelectionsForVariable = useCallback((variableName: string): VariableStatsSelection => {
    if (!variableName) return createDefaultStatsSelection();
    const current = variableStatsSelections[variableName];
    if (!current) {
      return createDefaultStatsSelection();
    }
    return { ...createDefaultStatsSelection(), ...current };
  }, [variableStatsSelections]);

  const handleToggleStatSelection = useCallback((variableName: string, key: keyof VariableStatsSelection) => {
    if (!variableName) return;
    setVariableStatsSelections(prev => {
      const existing = prev[variableName];
      const merged = existing ? { ...createDefaultStatsSelection(), ...existing } : createDefaultStatsSelection();
      const updatedValue = !merged[key];
      const updatedSelection = { ...merged, [key]: updatedValue };
      return {
        ...prev,
        [variableName]: updatedSelection,
      };
    });
  }, []);

  const handleSortPreferenceChange = useCallback((variableName: string, value: 'default' | 'frequency', persistFalse = false) => {
    if (!variableName) return;
    setVariableSortByFrequency(prev => {
      if (value === 'frequency') {
        return { ...prev, [variableName]: true };
      }
      if (persistFalse) {
        return { ...prev, [variableName]: false };
      }
      const { [variableName]: _removed, ...rest } = prev;
      return rest;
    });
    if (value === 'default') {
      setVariableHoldResponseCodes(prev => {
        if (!(variableName in prev)) {
          return prev;
        }
        const { [variableName]: _removed, ...rest } = prev;
        return rest;
      });
      setHoldOptionsDropdownOpen(prev => {
        if (!(variableName in prev)) {
          return prev;
        }
        const { [variableName]: _removed, ...rest } = prev;
        return rest;
      });
    }
  }, []);

  const handleToggleIndividualTable = useCallback((variableName: string, tableName: string, allTableNames: string[], initialSelectedNames?: string[]) => {
    if (!variableName || !tableName) return;
    setVariableTableSelections(prev => {
      const currentSet = prev[variableName];
      // Initialize with empty Set if no current selection exists
      // The isTableSelected function handles defaults, so we don't need to pre-populate
      const baseSet = currentSet ? new Set(currentSet) : new Set(initialSelectedNames || []);
      if (baseSet.has(tableName)) {
        baseSet.delete(tableName);
      } else {
        baseSet.add(tableName);
      }
      return {
        ...prev,
        [variableName]: baseSet,
      };
    });
  }, []);

  const handleSelectAllIndividualTables = useCallback((variableName: string, individualTableIds: string[], allTableIds: string[]) => {
    if (!variableName) return;
    setVariableTableSelections(prev => {
      const baseSet = prev[variableName] ? new Set(prev[variableName]) : new Set(allTableIds);
      individualTableIds.forEach(id => baseSet.add(id));
      if (baseSet.size === allTableIds.length) {
        const next = { ...prev };
        delete next[variableName];
        return next;
      }
      return {
        ...prev,
        [variableName]: baseSet,
      };
    });
  }, []);

  const handleUnselectAllIndividualTables = useCallback((variableName: string, individualTableIds: string[], allTableIds: string[]) => {
    if (!variableName) return;
    setVariableTableSelections(prev => {
      const baseSet = prev[variableName] ? new Set(prev[variableName]) : new Set(allTableIds);
      individualTableIds.forEach(id => baseSet.delete(id));
      return {
        ...prev,
        [variableName]: baseSet,
      };
    });
  }, []);

  const removeSummarySortSelection = useCallback((variableName: string, tableName: string) => {
    if (!variableName || !tableName) return;
    setSummaryTableSortSelections(prev => {
      const currentSet = prev[variableName];
      if (!currentSet || !currentSet.has(tableName)) return prev;
      const updatedSet = new Set(currentSet);
      updatedSet.delete(tableName);
      const nextState = { ...prev };
      if (updatedSet.size === 0) {
        delete nextState[variableName];
      } else {
        nextState[variableName] = updatedSet;
      }
      return nextState;
    });
  }, []);

  const handleSummaryTableSortToggle = useCallback((variableName: string, tableName: string, defaultOn: boolean) => {
    if (!variableName || !tableName) return;
    setSummaryTableSortSelections(prev => {
      const currentSet = prev[variableName] ? new Set(prev[variableName]) : new Set<string>();
      const isCurrentlyStored = currentSet.has(tableName);
      const isCurrentlyOn = defaultOn ? !isCurrentlyStored : isCurrentlyStored;
      const nextIsOn = !isCurrentlyOn;

      if (defaultOn) {
        if (nextIsOn) {
          currentSet.delete(tableName);
        } else {
          currentSet.add(tableName);
        }
      } else {
        if (nextIsOn) {
          currentSet.add(tableName);
        } else {
          currentSet.delete(tableName);
        }
      }

      const nextState = { ...prev };
      if (currentSet.size === 0) {
        delete nextState[variableName];
      } else {
        nextState[variableName] = currentSet;
      }
      return nextState;
    });
  }, []);

  const handleHoldOptionsToggle = useCallback((variableName: string, enabled: boolean, defaultCodes: string[] = []) => {
    if (!variableName) return;
    setVariableHoldResponseCodes(prev => {
      if (!enabled) {
        const { [variableName]: _removed, ...rest } = prev;
        return rest;
      }
      const existing = prev[variableName];
      if (existing && existing.length > 0) {
        return prev;
      }
      return { ...prev, [variableName]: defaultCodes };
    });
    if (!enabled) {
      setHoldOptionsDropdownOpen(prev => {
        if (!(variableName in prev)) return prev;
        const { [variableName]: _removed, ...rest } = prev;
        return rest;
      });
    }
  }, []);

  const handleHoldOptionSelection = useCallback((variableName: string, code: string) => {
    if (!variableName) return;
    setVariableHoldResponseCodes(prev => {
      const current = prev[variableName] || [];
      const exists = current.includes(code);
      const updated = exists ? current.filter(c => c !== code) : [...current, code];
      return { ...prev, [variableName]: updated };
    });
  }, []);

  const applyHoldOrdering = useCallback((items: any[], variableName: string, getCode: (item: any) => string) => {
    const holdList = variableHoldResponseCodes[variableName];
    if (!holdList || holdList.length === 0) {
      return items;
    }
    const holdSet = new Set(holdList);
    const remaining: any[] = [];
    items.forEach(item => {
      const code = getCode(item);
      if (!holdSet.has(code)) {
        remaining.push(item);
      }
    });
    const held: any[] = [];
    holdList.forEach(code => {
      const match = items.find(item => getCode(item) === code);
      if (match) {
        held.push(match);
      }
    });
    return [...remaining, ...held];
  }, [variableHoldResponseCodes]);

  const openHoldOptionsDropdown = useCallback((variableName: string) => {
    if (!variableName) return;
    setHoldOptionsDropdownOpen(prev => ({ ...prev, [variableName]: true }));
  }, []);
  const closeHoldOptionsDropdown = useCallback((variableName: string) => {
    if (!variableName) return;
    setHoldOptionsDropdownOpen(prev => {
      if (!prev[variableName]) return prev;
      const { [variableName]: _removed, ...rest } = prev;
      return rest;
    });
  }, []);

  const handleAddInlineNumericNet = useCallback((variableName: string) => {
    if (!variableName) return;
    setNetSummaryTableRanges(prev => {
      const existing = prev[variableName] || [];
      return {
        ...prev,
        [variableName]: [...existing, { name: '', low: '', high: '', context: 'stats' }],
      };
    });
  }, []);

  const handleUpdateInlineNumericNet = useCallback((variableName: string, globalIndex: number, key: 'name' | 'low' | 'high', value: string) => {
    if (!variableName) return;
    setNetSummaryTableRanges(prev => {
      const existing = prev[variableName] || [];
      if (!existing[globalIndex]) return prev;
      const updated = [...existing];
      updated[globalIndex] = { ...updated[globalIndex], [key]: value };
      const lowVal = parseFloat(updated[globalIndex].low);
      const highVal = parseFloat(updated[globalIndex].high);
      if (!isNaN(lowVal) && !isNaN(highVal) && lowVal > highVal) {
        if (key === 'low') {
          updated[globalIndex].high = updated[globalIndex].low;
        } else if (key === 'high') {
          updated[globalIndex].low = updated[globalIndex].high;
        }
      }
      return {
        ...prev,
        [variableName]: updated,
      };
    });
  }, []);

  const handleRemoveInlineNumericNet = useCallback((variableName: string, globalIndex: number) => {
    if (!variableName) return;
    setNetSummaryTableRanges(prev => {
      const existing = prev[variableName] || [];
      if (!existing[globalIndex]) return prev;
      const updated = existing.filter((_, idx) => idx !== globalIndex);
      return {
        ...prev,
        [variableName]: updated,
      };
    });
  }, []);

  const openNetSummaryModal = useCallback((variableName: string, config?: {
    mode?: 'range' | 'codes';
    responseOptions?: Array<{ code: string; text: string }>;
    initialName?: string;
    initialLow?: string;
    initialHigh?: string;
    initialCodes?: string[];
    editingIndex?: number | null;
  }) => {
    if (!variableName) return;
    setNetSummaryModalState({
      ...NET_SUMMARY_MODAL_DEFAULT,
      variableName,
      isOpen: true,
      mode: config?.mode ?? 'range',
      responseOptions: config?.responseOptions ?? [],
      name: config?.initialName ?? '',
      low: config?.initialLow ?? '',
      high: config?.initialHigh ?? '',
      selectedCodes: config?.initialCodes ?? [],
      editingIndex: config?.editingIndex ?? null,
    });
  }, []);

  const closeNetSummaryModal = useCallback(() => {
    setNetSummaryModalState({ ...NET_SUMMARY_MODAL_DEFAULT });
  }, []);

  const handleNetSummaryModalFieldChange = useCallback((field: 'name' | 'low' | 'high', value: string) => {
    setNetSummaryModalState(prev => ({
      ...prev,
      [field]: field === 'name' ? value : value.replace(/[^0-9.-]/g, ''),
      error: undefined,
    }));
  }, []);

  const handleNetSummaryModalCodeToggle = useCallback((code: string) => {
    setNetSummaryModalState(prev => {
      const exists = prev.selectedCodes.includes(code);
      const updatedCodes = exists
        ? prev.selectedCodes.filter(c => c !== code)
        : [...prev.selectedCodes, code];
      return {
        ...prev,
        selectedCodes: updatedCodes,
        error: undefined,
      };
    });
  }, []);

  const handleEditNetSummary = useCallback((variableName: string, netMeta: { type: 'range' | 'codes'; index: number }, responseOptions: Array<{ code: string; text: string }>) => {
    if (!variableName) return;
    if (netMeta.type === 'range') {
      const net = netSummaryTableRanges[variableName]?.[netMeta.index];
      if (!net) return;
      openNetSummaryModal(variableName, {
        mode: 'range',
        initialName: net.name || '',
        initialLow: net.low || '',
        initialHigh: net.high || '',
        editingIndex: netMeta.index,
      });
    } else {
      const net = netSummaryTableSelectedCodes[variableName]?.[netMeta.index];
      if (!net) return;
      openNetSummaryModal(variableName, {
        mode: 'codes',
        responseOptions,
        initialName: net.name || '',
        initialCodes: net.codes || [],
        editingIndex: netMeta.index,
      });
    }
  }, [netSummaryTableRanges, netSummaryTableSelectedCodes, openNetSummaryModal]);

  const handleNetSummaryModalSave = useCallback(() => {
    const { variableName, name, low, high, mode, selectedCodes } = netSummaryModalState;
    if (!variableName) {
      closeNetSummaryModal();
      return;
    }
    const trimmedName = name.trim();
    const trimmedLow = low.trim();
    const trimmedHigh = high.trim();
    if (mode === 'codes') {
      if (!trimmedName) {
        setNetSummaryModalState(prev => ({ ...prev, error: 'Enter a net name.' }));
        return;
      }
      if (selectedCodes.length === 0) {
        setNetSummaryModalState(prev => ({ ...prev, error: 'Select at least one response option.' }));
        return;
      }
      if (netSummaryModalState.editingIndex !== null) {
        setNetSummaryTableSelectedCodes(prev => {
          const existing = prev[variableName] || [];
          if (!existing[netSummaryModalState.editingIndex]) return prev;
          const updated = [...existing];
          updated[netSummaryModalState.editingIndex] = {
            ...updated[netSummaryModalState.editingIndex],
            name: trimmedName,
            codes: selectedCodes,
          };
          return {
            ...prev,
            [variableName]: updated,
          };
        });
        closeNetSummaryModal();
        return;
      }
      let newCodeIndex = 0;
      setNetSummaryTableSelectedCodes(prev => {
        const existing = prev[variableName] || [];
        newCodeIndex = existing.length;
        return {
          ...prev,
          [variableName]: [...existing, { name: trimmedName, codes: selectedCodes }],
        };
      });
      const newTableId = `${variableName}_NetSummaryTable_${newCodeIndex}`;
      setVariableTableSelections(prev => {
        const current = prev[variableName];
        if (!current) return prev;
        const updated = new Set(current);
        updated.add(newTableId);
        return {
          ...prev,
          [variableName]: updated,
        };
      });

      closeNetSummaryModal();
      return;
    }

    if (!trimmedName || !trimmedLow || !trimmedHigh) {
      setNetSummaryModalState(prev => ({ ...prev, error: 'Enter a name and both range values.' }));
      return;
    }
    const parsedLow = parseFloat(trimmedLow);
    const parsedHigh = parseFloat(trimmedHigh);
    if (isNaN(parsedLow) || isNaN(parsedHigh)) {
      setNetSummaryModalState(prev => ({ ...prev, error: 'Low and high must be numeric.' }));
      return;
    }
    if (parsedHigh < parsedLow) {
      setNetSummaryModalState(prev => ({ ...prev, error: 'High value must be greater than or equal to low.' }));
      return;
    }
    if (netSummaryModalState.editingIndex !== null) {
      setNetSummaryTableRanges(prev => {
        const existing = prev[variableName] || [];
        if (!existing[netSummaryModalState.editingIndex]) return prev;
        const updated = [...existing];
        updated[netSummaryModalState.editingIndex] = {
          ...updated[netSummaryModalState.editingIndex],
          name: trimmedName,
          low: trimmedLow,
          high: trimmedHigh,
        };
        return {
          ...prev,
          [variableName]: updated,
        };
      });
      closeNetSummaryModal();
      return;
    }

    let newNetIndex = 0;
    setNetSummaryTableRanges(prev => {
      const existing = prev[variableName] || [];
      const summaryCount = existing.filter(net => net.context === 'summary').length;
      newNetIndex = summaryCount;
      return {
        ...prev,
        [variableName]: [...existing, { name: trimmedName, low: trimmedLow, high: trimmedHigh, context: 'summary' }],
      };
    });

    const newTableId = `${variableName}_NetSummaryTable_${newNetIndex}`;
    setVariableTableSelections(prev => {
      const current = prev[variableName];
      if (!current) return prev;
      const updated = new Set(current);
      updated.add(newTableId);
      return {
        ...prev,
        [variableName]: updated,
      };
    });

    closeNetSummaryModal();
  }, [netSummaryModalState, closeNetSummaryModal, setNetSummaryTableRanges, setVariableTableSelections]);

  const [openSummaryDropdown, setOpenSummaryDropdown] = useState<Record<string, boolean>>({});
  const [editingTableName, setEditingTableName] = useState<Record<string, boolean>>({});
  const [tableNameInputs, setTableNameInputs] = useState<Record<string, string>>({});
  const [crosstabDownloads, setCrosstabDownloads] = useState<Array<{
    id: string;
    name: string;
    bannerName: string;
    sampleSize: number;
    status: 'generating' | 'completed';
    blob?: Blob;
  }>>([]);
  const [isGeneratingCrosstab, setIsGeneratingCrosstab] = useState(false);
  const [selectedCrosstabBannerId, setSelectedCrosstabBannerId] = useState<string | null>(null);
  const [exportingBannerId, setExportingBannerId] = useState<string | null>(null);
  // In-UI Stat debug
  const [showStatDebug, setShowStatDebug] = useState(false);
  const [statDebugLogs, setStatDebugLogs] = useState<string[]>([]);
  const appendStatLog = React.useCallback((msg: string, data?: any) => {
    const enabled = (globalThis as any).__TABEXPORT_DEBUG_STATS === true || showStatDebug;
    if (!enabled) return;
    const line = data !== undefined ? `${msg} ${(() => { try { return JSON.stringify(data); } catch { return String(data); } })()}` : msg;
    setStatDebugLogs(prev => {
      const next = [...prev, line];
      // keep last 300 lines
      return next.length > 300 ? next.slice(next.length - 300) : next;
    });
    // Also mirror to console for easy copying
    // eslint-disable-next-line no-console
    console.warn('[STAT DEBUG UI]', msg, data ?? '');
  }, [showStatDebug]);

  // Silence console messages when tab specs page is active (keep errors for debugging)
  useEffect(() => {
    if (qnrViewMode === 'tabSpecs') {
      // Store original console methods
      const originalLog = console.log;
      const originalWarn = console.warn;
      const originalDebug = console.debug;
      const originalInfo = console.info;

      // Override console methods to be silent (keep error for actual errors)
      console.log = () => {};
      console.warn = () => {};
      console.debug = () => {};
      console.info = () => {};

      // Restore original methods when component unmounts or view changes
      return () => {
        console.log = originalLog;
        console.warn = originalWarn;
        console.debug = originalDebug;
        console.info = originalInfo;
      };
    }
  }, [qnrViewMode]);

  // Load new banner groups from localStorage when questionnaire changes
  useEffect(() => {
    if (selectedQuestionnaire?.id) {
      const key = `newBannerGroups_${selectedQuestionnaire.id}`;
      const stored = localStorage.getItem(key);
      if (stored) {
        try {
          const parsed = JSON.parse(stored);
          setNewBannerGroups(parsed || []);
        } catch (e) {
        }
      } else {
        setNewBannerGroups([]);
      }
    } else {
      setNewBannerGroups([]);
    }
  }, [selectedQuestionnaire?.id]);

  // Save new banner groups to localStorage when they change
  useEffect(() => {
    if (selectedQuestionnaire?.id && newBannerGroups.length > 0) {
      const key = `newBannerGroups_${selectedQuestionnaire.id}`;
      localStorage.setItem(key, JSON.stringify(newBannerGroups));
    }
  }, [newBannerGroups, selectedQuestionnaire?.id]);

  // Load banner filter conditions from localStorage when questionnaire changes
  useEffect(() => {
    if (selectedQuestionnaire?.id) {
      const key = `bannerFilterConditions_${selectedQuestionnaire.id}`;
      const stored = localStorage.getItem(key);
      if (stored) {
        try {
          const parsed = JSON.parse(stored);
          setBannerFilterConditions(parsed || null);
        } catch (e) {
          setBannerFilterConditions(null);
        }
      } else {
        setBannerFilterConditions(null);
      }
    } else {
      setBannerFilterConditions(null);
    }
  }, [selectedQuestionnaire?.id]);

  // Save banner filter conditions to localStorage when they change
  useEffect(() => {
    if (selectedQuestionnaire?.id) {
      const key = `bannerFilterConditions_${selectedQuestionnaire.id}`;
      if (bannerFilterConditions && bannerFilterConditions.length > 0) {
        localStorage.setItem(key, JSON.stringify(bannerFilterConditions));
      } else {
        localStorage.removeItem(key);
      }
    }
  }, [bannerFilterConditions, selectedQuestionnaire?.id]);

  // Initialize hiddenFromBanners: hide open ends and open end lists by default
  useEffect(() => {
    if (selectedQuestionnaire?.id) {
      const key = `hiddenFromBanners_${selectedQuestionnaire.id}`;
      const stored = localStorage.getItem(key);
      
      if (stored) {
        try {
          const parsed = JSON.parse(stored);
          setHiddenFromBanners(new Set(parsed));
        } catch (e) {
          // Initialize with defaults if loading fails
          if (variables.length > 0) {
            const defaultHidden = new Set<string>();
            variables.forEach(v => {
              const isOpenEnd = v.type?.toLowerCase().includes('open end');
              if (isOpenEnd) {
                defaultHidden.add(v.name);
              }
            });
            setHiddenFromBanners(defaultHidden);
          }
        }
      } else if (variables.length > 0) {
        // Initialize with defaults: hide open ends and open end lists
        const defaultHidden = new Set<string>();
        variables.forEach(v => {
          const isOpenEnd = v.type?.toLowerCase().includes('open end');
          if (isOpenEnd) {
            defaultHidden.add(v.name);
          }
        });
        setHiddenFromBanners(defaultHidden);
      }
    } else {
      setHiddenFromBanners(new Set());
    }
  }, [selectedQuestionnaire?.id, variables]);

  // Load saved coding themes from localStorage
  useEffect(() => {
    if (selectedQuestionnaire?.id) {
      const storageKey = `codingThemes_${selectedQuestionnaire.id}`;
      const stored = localStorage.getItem(storageKey);

      if (stored) {
        try {
          const themesMap = JSON.parse(stored);
          const newMap = new Map<string, Array<{ code: number; theme: string }>>();
          Object.entries(themesMap).forEach(([varName, themes]) => {
            newMap.set(varName, themes as Array<{ code: number; theme: string }>);
          });
          setSavedCodingThemes(newMap);
        } catch (e) {
          console.error('Error loading coding themes from localStorage:', e);
          setSavedCodingThemes(new Map());
        }
      } else {
        setSavedCodingThemes(new Map());
      }
    } else {
      setSavedCodingThemes(new Map());
    }
  }, [selectedQuestionnaire?.id]);

  // Load coded headers debug from localStorage
  useEffect(() => {
    if (selectedQuestionnaire?.id) {
      const storageKey = `codedHeadersDebug_${selectedQuestionnaire.id}`;
      const stored = localStorage.getItem(storageKey);
      if (stored) {
        try {
          const obj = JSON.parse(stored) as Record<string, string[]>;
          setCodedHeadersDebug(obj || {});
        } catch (e) {
          console.error('Error loading coded headers debug from localStorage:', e);
          setCodedHeadersDebug({});
        }
      } else {
        setCodedHeadersDebug({});
      }
    } else {
      setCodedHeadersDebug({});
    }
  }, [selectedQuestionnaire?.id]);

  // Save hiddenFromBanners to localStorage when it changes
  useEffect(() => {
    if (selectedQuestionnaire?.id) {
      const key = `hiddenFromBanners_${selectedQuestionnaire.id}`;
      if (hiddenFromBanners.size > 0) {
        localStorage.setItem(key, JSON.stringify(Array.from(hiddenFromBanners)));
      } else {
        localStorage.removeItem(key);
      }
    }
  }, [hiddenFromBanners, selectedQuestionnaire?.id]);

  // Auto-initialize nets for numeric questions with % tag
  useEffect(() => {
    if (selectedQuestionnaire?.id && variables.length > 0) {
      const key = `netSummaryTableRanges_${selectedQuestionnaire.id}`;
      const stored = localStorage.getItem(key);
      let existingNets: Record<string, NetRange[]> = {};
      
      if (stored) {
        try {
          existingNets = JSON.parse(stored);
        } catch (e) {
          // If parsing fails, start fresh
        }
      }
      
      // Check each variable and auto-initialize nets for numeric questions with % tag
      const updatedNets = { ...existingNets };
      let hasChanges = false;

      variables.forEach(variable => {
        const isNumericQuestion = variable.type?.toLowerCase().includes('numeric') &&
                                  !variable.type?.toLowerCase().includes('grid');
        const isNumericGrid = variable.type?.toLowerCase().includes('numeric grid');
        const hasPercentTag = variable.tags && Array.isArray(variable.tags) && variable.tags.includes('%');

        // Check if numeric grid has only 1 column
        let isSingleColumnGrid = false;
        if (isNumericGrid) {
          const baseNumber = variable.name.replace(/^Q/, '');
          const question = questionnaireQuestions.find(q => {
            const qNum = q.number || q.id;
            return qNum === baseNumber ||
                   qNum === baseNumber.replace(/^Q/, '') ||
                   String(qNum) === String(baseNumber);
          });

          if (question && question.responseOptions && Array.isArray(question.responseOptions)) {
            isSingleColumnGrid = question.responseOptions.length === 1;
          }
        }

        // Only auto-initialize if it's a numeric question with % tag OR single-column numeric grid with % tag
        if (hasPercentTag && (isNumericQuestion || isSingleColumnGrid) && (!updatedNets[variable.name] || updatedNets[variable.name].length === 0)) {
          updatedNets[variable.name] = [
            { name: '0-20%', low: '0', high: '20', context: 'stats' },
            { name: '21-40%', low: '21', high: '40', context: 'stats' },
            { name: '41-60%', low: '41', high: '60', context: 'stats' },
            { name: '61-80%', low: '61', high: '80', context: 'stats' },
            { name: '81-100%', low: '81', high: '100', context: 'stats' }
          ];
          hasChanges = true;
        }
      });

      // Always set the state to include both loaded and newly initialized nets
      if (hasChanges || Object.keys(existingNets).length > 0) {
        setNetSummaryTableRanges(updatedNets);
        if (hasChanges) {
          localStorage.setItem(key, JSON.stringify(updatedNets));
        }
      }
    }
  }, [selectedQuestionnaire?.id, variables, questionnaireQuestions]);

  useEffect(() => {
    if (!selectedQuestionnaire?.id) return;
    const key = `netSummaryTableRanges_${selectedQuestionnaire.id}`;
    if (Object.keys(netSummaryTableRanges).length > 0) {
      localStorage.setItem(key, JSON.stringify(netSummaryTableRanges));
    } else {
      localStorage.removeItem(key);
    }
  }, [netSummaryTableRanges, selectedQuestionnaire?.id]);

  // Auto-initialize scale nets (T2B, M3B, B2B) for single select questions with Scale (7pt) tag
  useEffect(() => {
    if (selectedQuestionnaire?.id && variables.length > 0) {
      const key = `netSummaryTableSelectedCodes_${selectedQuestionnaire.id}`;
      const stored = localStorage.getItem(key);
      let existingCodes: Record<string, NetCodeSelection[]> = {};
      
      if (stored) {
        try {
          existingCodes = JSON.parse(stored);
        } catch (e) {
          // If parsing fails, start fresh
        }
      }
      
      // Also merge with current state (in case state was reset but localStorage still has data)
      const currentState = netSummaryTableSelectedCodes;
      const mergedCodes = { ...existingCodes };
      Object.keys(currentState).forEach(varName => {
        if (currentState[varName] && currentState[varName].length > 0) {
          mergedCodes[varName] = currentState[varName];
        }
      });
      
      // Check each variable and auto-initialize scale nets for single select questions with Scale (7pt) tag
      const updatedCodes = { ...mergedCodes };
      let hasChanges = false;

      variables.forEach(variable => {
        const isSingleSelect = variable.type?.toLowerCase().includes('single select');
        const isSingleSelectGrid = variable.type?.toLowerCase().includes('single select grid');
        const isBaseSingleSelect = isSingleSelect && !isSingleSelectGrid;
        const isScaleSummary = (variable as any).isScaleSummary;
        
        if ((isBaseSingleSelect || isSingleSelectGrid) && !isScaleSummary) {
          // Check for Scale (7pt) tag on variable or question
          let scaleTag = variable.tags && Array.isArray(variable.tags) 
            ? variable.tags.find((tag: string) => tag.startsWith('Scale ('))
            : null;
          
          // For single select grids, also check the question's tags
          if (!scaleTag && isSingleSelectGrid) {
            const baseNumber = variable.name.replace(/^Q/, '');
            const question = questionnaireQuestions.find(q => {
              const qNum = q.number || q.id;
              return qNum === baseNumber ||
                     qNum === baseNumber.replace(/^Q/, '') ||
                     String(qNum) === String(baseNumber);
            });
            if (question && question.tags && Array.isArray(question.tags)) {
              scaleTag = question.tags.find((tag: string) => tag.startsWith('Scale ('));
            }
          }
          
          const scaleType = scaleTag ? scaleTag.match(/Scale \((\d+)pt\)/)?.[1] : null;
          const is7PointScale = scaleType === '7';
          
          // Auto-initialize scale nets for 7-point scales
          if (is7PointScale && (!updatedCodes[variable.name] || updatedCodes[variable.name].length === 0)) {
            // Get actual codes from variable and sort them numerically
            // For single select grids, variable.codes contains the response options (columns)
            let codes = variable.codes ? Object.keys(variable.codes) : [];
            
            // For single select grids, also try to get codes from the question's responseOptions
            if (isSingleSelectGrid && codes.length === 0) {
              const baseNumber = variable.name.replace(/^Q/, '');
              const question = questionnaireQuestions.find(q => {
                const qNum = q.number || q.id;
                return qNum === baseNumber ||
                       qNum === baseNumber.replace(/^Q/, '') ||
                       String(qNum) === String(baseNumber);
              });
              if (question && question.responseOptions && Array.isArray(question.responseOptions)) {
                codes = question.responseOptions.map((opt: any, idx: number) => {
                  if (typeof opt === 'string') {
                    const codeMatch = opt.match(/^(\d+):?\s+(.+)$/);
                    return codeMatch ? codeMatch[1] : String(idx + 1);
                  }
                  const code = opt.code || String(idx + 1);
                  return code.replace(/^c/i, '');
                });
              }
            }
            // Extract numeric values from codes (handle formats like "1", "r1", "c1", etc.)
            const numericCodes = codes
              .map(code => {
                // Extract numeric part from code (e.g., "r1" -> 1, "1" -> 1, "c1" -> 1)
                const match = code.match(/(\d+)/);
                return match ? { code, num: parseInt(match[1], 10) } : null;
              })
              .filter((item): item is { code: string; num: number } => item !== null)
              .sort((a, b) => a.num - b.num);
            
            if (numericCodes.length >= 7) {
              // Get the highest 2 codes for T2B, middle 3 for M3B, lowest 2 for B2B
              const highest2 = numericCodes.slice(-2).map(item => item.code);
              const middle3 = numericCodes.slice(-5, -2).map(item => item.code);
              const lowest2 = numericCodes.slice(0, 2).map(item => item.code);
              
              updatedCodes[variable.name] = [
                { name: 'Top 2 Box (T2B)', codes: highest2 },
                { name: 'Middle 3 Box (M3B)', codes: middle3 },
                { name: 'Bottom 2 Box (B2B)', codes: lowest2 }
              ];
              hasChanges = true;
            } else {
              // Fallback to hardcoded values if we can't determine codes
              // Try to match against common code formats for single select grids
              const possibleCodes = ['1', '2', '3', '4', '5', '6', '7', 'c1', 'c2', 'c3', 'c4', 'c5', 'c6', 'c7'];
              const matchingCodes: string[] = [];
              
              // Find matching codes from the variable's codes
              possibleCodes.forEach(possibleCode => {
                const found = codes.find(code => {
                  const codeNum = code.replace(/^c/i, '');
                  const possibleNum = possibleCode.replace(/^c/i, '');
                  return code === possibleCode || codeNum === possibleNum;
                });
                if (found) {
                  matchingCodes.push(found);
                }
              });
              
              if (matchingCodes.length >= 7) {
                // Sort the matching codes numerically
                const numericMatching = matchingCodes
                  .map(code => {
                    const match = code.match(/(\d+)/);
                    return match ? { code, num: parseInt(match[1], 10) } : null;
                  })
                  .filter((item): item is { code: string; num: number } => item !== null)
                  .sort((a, b) => a.num - b.num);
                
                const highest2 = numericMatching.slice(-2).map(item => item.code);
                const middle3 = numericMatching.slice(-5, -2).map(item => item.code);
                const lowest2 = numericMatching.slice(0, 2).map(item => item.code);
                
                updatedCodes[variable.name] = [
                  { name: 'Top 2 Box (T2B)', codes: highest2 },
                  { name: 'Middle 3 Box (M3B)', codes: middle3 },
                  { name: 'Bottom 2 Box (B2B)', codes: lowest2 }
                ];
                hasChanges = true;
              } else {
                // Final fallback - use the actual codes from variable if available, otherwise use defaults
                const t2bCodes: string[] = [];
                const m3bCodes: string[] = [];
                const b2bCodes: string[] = [];
                
                // Try to find codes matching 6, 7 for T2B
                codes.forEach(code => {
                  const num = code.replace(/^c/i, '');
                  if (num === '6' || num === '7') t2bCodes.push(code);
                  else if (num === '3' || num === '4' || num === '5') m3bCodes.push(code);
                  else if (num === '1' || num === '2') b2bCodes.push(code);
                });
                
                updatedCodes[variable.name] = [
                  { name: 'Top 2 Box (T2B)', codes: t2bCodes.length >= 2 ? t2bCodes : ['6', '7'] },
                  { name: 'Middle 3 Box (M3B)', codes: m3bCodes.length >= 3 ? m3bCodes : ['3', '4', '5'] },
                  { name: 'Bottom 2 Box (B2B)', codes: b2bCodes.length >= 2 ? b2bCodes : ['1', '2'] }
                ];
                hasChanges = true;
              }
            }
          }
        }
      });

      // Always set the state to include both loaded and newly initialized codes
      // Also check if current state is empty but we have codes to restore/create
      const currentStateEmpty = Object.keys(netSummaryTableSelectedCodes).length === 0;
      const hasCodesToSet = hasChanges || Object.keys(updatedCodes).length > 0;
      
      // Compare current state with updated codes to prevent infinite loop
      const currentStateStr = JSON.stringify(netSummaryTableSelectedCodes);
      const updatedCodesStr = JSON.stringify(updatedCodes);
      const codesChanged = currentStateStr !== updatedCodesStr;
      
      if ((hasCodesToSet || currentStateEmpty) && codesChanged) {
        setNetSummaryTableSelectedCodes(updatedCodes);
        if (hasChanges || Object.keys(updatedCodes).length > 0) {
          localStorage.setItem(key, JSON.stringify(updatedCodes));
        }
      }
    }
  }, [selectedQuestionnaire?.id, variables, specsResetKey, questionnaireQuestions]);

  useEffect(() => {
    if (!selectedQuestionnaire?.id) return;
    const key = `netSummaryTableSelectedCodes_${selectedQuestionnaire.id}`;
    if (Object.keys(netSummaryTableSelectedCodes).length > 0) {
      localStorage.setItem(key, JSON.stringify(netSummaryTableSelectedCodes));
    }
    // Don't remove from localStorage on empty - let auto-initialization handle it
  }, [netSummaryTableSelectedCodes, selectedQuestionnaire?.id]);

